contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target, bool freeze, address other) public payable {
        require(other != target);
        bool beforeOther = c.frozenAccount(other); if (__ESBMC_reverted()) return;
        c.freezeAccount(target, freeze); if (__ESBMC_reverted()) return;
        bool afterTarget = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        bool afterOther = c.frozenAccount(other); if (__ESBMC_reverted()) return;
        assert(afterTarget == freeze && afterOther == beforeOther);
    }
}

